// Looks up the blur placeholder for a photo.
//
// content/blur-data.json is generated by scripts/generate-blur.mjs, which runs
// automatically before `npm run dev` and `npm run build`. Only import this
// file from server components (not files marked "use client"), otherwise the
// whole JSON file is sent to the browser.

import blurData from "@/content/blur-data.json";

const blurBySrc: Record<string, string> = blurData;

export function getBlurDataURL(src: string): string | undefined {
  return blurBySrc[src];
}
